      "years": [2021, 2022],
      "pattern": "shock",
      "direction": "increase",
      "magnitude": "~+0.35–0.40 A/E points, peaking at ~1.28–1.30",
      "confidence": 0.95,
      "evidence": [
        "ae_ci_by_year.csv: A/E jumps from 0.880 (2020) to 1.273 (2021), holds at 1.295 (2022), then reverts to ~0.94 in 2023–2024",
        "Expected claims >1,300 in spike years imply Poisson std dev ~0.025; observed shift exceeds 10 sigma",
        "ae_ci_by_year.png confirms a distinct flat-topped excursion without gradual ramp-up"
      ],
      "recommended_action": "Investigate 2021–2022 claim drivers (underwriting changes, product alterations, reporting/data errors, or genuine experience shift); validate data integrity; review CI pricing and reserving assumptions to assess whether the spike indicates a structural change or remains an isolated event."
    }
  ]
}

